		'1import\u001f0 { ColorPickerInput, ColorPickerSwatch, hueOf } \u001f1from\u001f0 \u001f4"@workspace/ui-native/components/color-picker"\u001f0;\n1import\u001f0 \u001f3*\u001f0 \u001f1as\u001f0 React \u001f1from\u001f0 \u001f4"react"\u001f0;\n1import\u001f0 { View } \u001f1from\u001f0 \u001f4"react-native"\u001f0;\n1import\u001f0 { hsvToRgb, toHex } \u001f1from\u001f0 \u001f4"@workspace/ui-native/lib/color"\u001f0;\n\n5/** The scale\'s brightness steps, light to dark. */\n1const\u001f0 \u001f3STEPS\u001f1:\u001f0 \u001f1readonly\u001f0 \u001f3number\u001f0[] \u001f1=\u001f0 [\u001f31\u001f0, \u001f30.9\u001f0, \u001f30.75\u001f0, \u001f30.6\u001f0, \u001f30.45\u001f0, \u001f30.3\u001f0];\n1const\u001f0 \u001f3PERCENT\u001f0 \u001f1=\u001f0 \u001f3100\u001f0;\n\n1export\u001f0 \u001f1function\u001f0 \u001f2ColorPicker14Example\u001f0()\u001f1:\u001f0 \u001f2React\u001f0.\u001f2JSX\u001f0.\u001f2Element\u001f0 {\n0\t\u001f1const\u001f0 [\u001f3base\u001f0, \u001f3setBase\u001f0] \u001f1=\u001f0 React.\u001f2useState\u001f0<\u001f3string\u001f0>(\u001f4"#8b5cf6"\u001f0);\n0\t\u001f1return\u001f0 (\n0\t\t<\u001f3View\u001f0 \u001f2className\u001f1=\u001f4"gap-3"\u001f0>\n0\t\t\t<\u001f3ColorPickerInput\u001f0 \u001f2value\u001f1=\u001f0{base} \u001f2onChange\u001f1=\u001f0{setBase} \u001f2accessibilityLabel\u001f1=\u001f4"Base colour"\u001f0 />\n0\t\t\t<\u001f3View\u001f0 \u001f2className\u001f1=\u001f4"flex-row flex-wrap gap-2"\u001f0>\n0\t\t\t\t{\u001f3STEPS\u001f0.\u001f2map\u001f0((\u001f7step\u001f1:\u001f0 \u001f3number\u001f0)\u001f1:\u001f0 \u001f2React\u001f0.\u001f2JSX\u001f0.\u001f2Element\u001f0 \u001f1=>\u001f0 (\n0\t\t\t\t\t<\u001f3ColorPickerSwatch\u001f0 \u001f2key\u001f1=\u001f0{step} \u001f2color\u001f1=\u001f0{\u001f2toHex\u001f0(\u001f2hsvToRgb\u001f0({ h: \u001f2hueOf\u001f0(base), s: \u001f30.85\u001f0, v: step, a: \u001f31\u001f0 }))} \u001f2label\u001f1=\u001f0{\u001f4`Brand ${\u001f2String\u001f4(\u001f0Math\u001f4.\u001f2round\u001f4(\u001f0step\u001f4 \u001f1*\u001f4 \u001f3PERCENT\u001f4))}`\u001f0} \u001f2size\u001f1=\u001f4"lg"\u001f0 />\n0\t\t\t\t))}\n0\t\t\t</\u001f3View\u001f0>\n0\t\t</\u001f3View\u001f0>\n0\t);\n0}',
